// Prunes the pydoc-markdown output down to the public SDK surface.
// Runs after `pydoc-markdown` (see the "generate-api-docs" npm script). Because the
// API sidebar is autogenerated from the files on disk, deleting a module's page also
// removes it from the sidebar — no manual sidebar bookkeeping required.
import {rmSync, readdirSync, existsSync, writeFileSync} from 'node:fs';
import {join} from 'node:path';

const API = 'docs/api/venice_ai';

// Internal-implementation subpackages with no public, user-imported surface.
const DROP_DIRS = [
  'cli',           // the `venice` CLI implementation (used as a command, not imported)
  'provider',      // adaptive-scheduler provider adapter
  'validation',    // internal validators
  'test_support',  // internal test scaffolding
];
for (const d of DROP_DIRS) {
  rmSync(join(API, d), {recursive: true, force: true});
}

// `core/` is mostly internal plumbing, but `core/config` holds public, user-imported
// config types (BackendConfig, SchedulerConfig, SchedulerMode, …) referenced by the
// README and guides. Keep config; drop the rest of core.
const coreDir = join(API, 'core');
if (existsSync(coreDir)) {
  for (const entry of readdirSync(coreDir, {withFileTypes: true})) {
    if (entry.name === 'config') continue;
    rmSync(join(coreDir, entry.name), {recursive: true, force: true});
  }
}
// `middleware` (retry) and `observability` are kept — both are referenced by the guides/skills.

// Private modules (single leading underscore), at any depth. Dunder files (e.g.
// __init__.md) are kept — they carry the package overviews.
function prunePrivate(dir) {
  for (const entry of readdirSync(dir, {withFileTypes: true})) {
    const p = join(dir, entry.name);
    if (entry.isDirectory()) prunePrivate(p);
    else if (/^_[^_].*\.md$/.test(entry.name)) rmSync(p, {force: true});
  }
}
prunePrivate(API);

// The pydoc-markdown sidebar.json is unused (the sidebar is autogenerated from files).
rmSync('docs/api/sidebar.json', {force: true});

// The top-level `venice_ai` package is the API sidebar's only top-level group. Expand it
// by default so landing on "API Reference" shows the module list rather than a lone
// collapsed entry. Nested subpackages stay collapsed for scannability.
writeFileSync(
  join(API, '_category_.json'),
  JSON.stringify({label: 'venice_ai', collapsed: false}, null, 2) + '\n',
);

console.log('Pruned API reference to the public surface.');
